CREATE TABLE IF NOT EXISTS PartReference (
 id TEXT PRIMARY KEY,
 partNumber TEXT NOT NULL,
 normalizedPartNumber TEXT NOT NULL,
 nameFa TEXT NOT NULL,
 nameEn TEXT NOT NULL,
 componentGroup TEXT NOT NULL,
 engineModels TEXT NOT NULL,
 sourceUrl TEXT NOT NULL,
 sourceTitle TEXT NOT NULL,
 sourceType TEXT NOT NULL DEFAULT 'public_supplier_catalog',
 fitmentNote TEXT NOT NULL,
 createdAt TEXT NOT NULL,
 UNIQUE(normalizedPartNumber,nameEn,sourceUrl)
);
CREATE INDEX IF NOT EXISTS PartReference_number_idx ON PartReference(normalizedPartNumber);
CREATE INDEX IF NOT EXISTS PartReference_group_idx ON PartReference(componentGroup);
CREATE INDEX IF NOT EXISTS PartReference_models_idx ON PartReference(engineModels);
